const storage={get(k,f=[]){try{return JSON.parse(localStorage.getItem('aibom_lab2_'+(query.get('qa')==='1'?'qa_':'')+k))??f}catch{return f}},set(k,v){try{localStorage.setItem('aibom_lab2_'+(query.get('qa')==='1'?'qa_':'')+k,JSON.stringify(v));return true}catch{toast('이 브라우저에서는 저장이 제한됩니다. 다운로드로 보관해주세요.');return false}}};
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',4000)}
function download(name,text,type='text/plain;charset=utf-8'){const blob=new Blob([type.startsWith('text/plain')?'\ufeff':'',text],{type}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),2000)}
async function copyText(t){try{await navigator.clipboard.writeText(t);toast('복사했습니다.')}catch{const a=document.createElement('textarea');a.value=t;document.body.append(a);a.select();const ok=document.execCommand('copy');a.remove();toast(ok?'복사했습니다.':'복사가 제한됩니다. 결과를 선택해서 복사해주세요.')}}
