document.addEventListener('click',e=>{const p=e.target.closest('[data-copy-prompt]');if(p)copyText(prompts[Number(p.dataset.copyPrompt)][2]);const d=e.target.closest('[data-download-work]');if(d){const w=storage.get('works').find(w=>w.id===d.dataset.downloadWork);if(w)download(w.filename,w.content,w.mime)}const v=e.target.closest('[data-view-work]');if(v){const w=storage.get('works').find(w=>w.id===v.dataset.viewWork);if(!w)return;$('#dialog-content').innerHTML=`<span class="tag demo">내 템플릿 체험 작품</span><h2 style="margin-top:15px">${esc(w.title)}</h2>`+(w.kind==='website'?'<iframe id="dialog-frame" class="dialog-frame" sandbox="" title="저장한 홈페이지 시안"></iframe>':w.kind==='image'?'<img id="dialog-image" class="dialog-image" alt="저장한 템플릿 이미지 시안">':`<div class="dialog-pre">${esc(w.content)}</div>`);if(w.kind==='website')$('#dialog-frame').srcdoc=w.content;if(w.kind==='image')$('#dialog-image').src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(w.content);$('#view-dialog').showModal()}});






function accountTeaser(){return `<section class="account-teaser"><div class="wrap account-teaser-row"><div><span class="tag">본인 계정 · 외부 AI 실습</span><h2>이제, 실제 AI로 만들어보세요.</h2><p>프롬프트를 준비하고 ChatGPT 이모티콘부터 Gemini·Firefly·vStory·Flow·Suno·CapCut까지 직접 실습하세요. 무료 한도부터 시작하고, 추가 이용은 본인의 요금제로 선택합니다.</p></div><a class="btn" href="account.html">내 계정으로 실습하기 ↗</a></div></section>`}

